public final class BountyBoardData extends SavedData {

    public static final String FILE_ID = "dynasty_bounty";
    private static final String TAG_PLAYERS = "players";
    private static final String TAG_ID = "id";
    private static final String TAG_LINES = "lines";

    private final Map<UUID, BountyStateMachine> players = new HashMap<>();

    public static BountyBoardData get(ServerLevel level) {
        MinecraftServer server = level.getServer();
        ServerLevel overworld = server.overworld();
        return overworld.getDataStorage().computeIfAbsent(BountyBoardData::load, BountyBoardData::new, FILE_ID);
    }

    public BountyStateMachine stateOf(UUID playerId) {
        BountyStateMachine state = players.get(playerId);
        if (state == null) {
            state = new BountyStateMachine();
            players.put(playerId, state);
            setDirty();
        }
        return state;
    }

    public int knownPlayers() {
        return players.size();
    }

    public static BountyBoardData load(CompoundTag tag) {
        BountyBoardData data = new BountyBoardData();
        ListTag list = tag.getList(TAG_PLAYERS, Tag.TAG_COMPOUND);
        for (int i = 0; i < list.size(); i++) {
            CompoundTag entry = list.getCompound(i);
            try {
                UUID id = UUID.fromString(entry.getString(TAG_ID));
                ListTag lines = entry.getList(TAG_LINES, Tag.TAG_STRING);
                data.players.put(id, BountyStateMachine.fromLines(
                        lines.stream().map(Tag::getAsString).toList()));
            } catch (RuntimeException ignored) {
                // 单个玩家记录坏了就跳过，不影响其他人
            }
        }
        return data;
    }

    @Override
    public CompoundTag save(CompoundTag tag) {
        ListTag list = new ListTag();
        for (Map.Entry<UUID, BountyStateMachine> entry : players.entrySet()) {
            CompoundTag record = new CompoundTag();
            record.putString(TAG_ID, entry.getKey().toString());
            ListTag lines = new ListTag();
            for (String line : entry.getValue().toLines()) {
                lines.add(StringTag.valueOf(line));
            }
            record.put(TAG_LINES, lines);
            list.add(record);
        }
        tag.put(TAG_PLAYERS, list);
        return tag;
    }

    /** 供测试与诊断：导出某个玩家的存档行。 */
    public List<String> dump(UUID playerId) {
        return stateOf(playerId).toLines();
    }
}

public static BountyStateMachine stateFor(ServerPlayer player) {
    ServerLevel overworld = player.server.overworld();
    BountyBoardData data = BountyBoardData.get(overworld);
    BountyStateMachine state = data.stateOf(player.getUUID());
    long effectiveDay = state.effectiveDay(BountyRules.dayOf(overworld.getDayTime()));
    if (state.needsPublication(effectiveDay)) {
        state.publish(effectiveDay, publishFor(effectiveDay));
        data.setDirty();
    }
    return state;
}

private static String doClaim(ServerPlayer player, BountyStateMachine state, String instanceId) {
    BountyStateMachine.Accepted record = state.acceptedById(instanceId);
    if (record == null) {
        return "dynasty.bounty.msg.not_accepted";
    }
    if (!record.done) {
        return "dynasty.bounty.msg.not_done";
    }
    BountyModel.Reward reward = record.instance.reward;
    int neededSlots = reward.allItems().size();
    if (!BountyRules.rewardFits(freeSlots(player), neededSlots)) {
        return "dynasty.bounty.msg.no_space";
    }
    BountyStateMachine.Claim result = state.claim(instanceId, true);
    if (result != BountyStateMachine.Claim.OK) {
        return switch (result) {
            case ALREADY_CLAIMED -> "dynasty.bounty.msg.already_claimed";
            case NOT_DONE -> "dynasty.bounty.msg.not_done";
            default -> "dynasty.bounty.msg.not_accepted";
        };
    }
    for (BountyModel.Stack stack : reward.allItems()) {
        net.minecraft.world.item.Item item = ForgeRegistries.ITEMS.getValue(new ResourceLocation(stack.item));
        if (item != null) {
            player.getInventory().add(new net.minecraft.world.item.ItemStack(item, stack.count));
        }
    }
    if (reward.experience > 0) {
        player.giveExperiencePoints(reward.experience);
    }
    return "dynasty.bounty.msg.claimed";
}

package com.dynasty.dungeon;

import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.saveddata.SavedData;
import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

/** Dimension-local keys isolate multiplayer rooms and survive core replacement. */
public final class DungeonStateStore extends SavedData {
    private final Map<String,DungeonRoomController> rooms=new HashMap<>();
    private final Map<String,DungeonEncounterState> encounters=new HashMap<>();
    private final Map<String,DungeonRewardReceipt> rewards=new HashMap<>();
    public static DungeonStateStore get(ServerLevel level){
        return level.getDataStorage().computeIfAbsent(DungeonStateStore::load,DungeonStateStore::new,"dynasty_dungeons_v1");
    }
    public DungeonRoomController room(UUID instance,String room){
        String key=instance+"/"+room;
        if(!rooms.containsKey(key)){rooms.put(key,new DungeonRoomController());setDirty();}
        return rooms.get(key);
    }
    public DungeonEncounterState encounter(UUID instance,String dungeon,boolean create){
        String key=instance+"/"+dungeon;
        if(create&&!encounters.containsKey(key)){encounters.put(key,new DungeonEncounterState());setDirty();}
        return encounters.get(key);
    }
    public DungeonRewardReceipt reward(String key){return rewards.get(key);}
    public DungeonRewardReceipt reserveReward(String key,UUID player,java.util.List<net.minecraft.world.item.ItemStack> items){
        if(!rewards.containsKey(key)){
            if(items.isEmpty()||items.size()>128)throw new IllegalArgumentException("Invalid reward bundle");
            rewards.put(key,new DungeonRewardReceipt(player,items));setDirty();
        }
        return rewards.get(key);
    }
    public static DungeonStateStore load(CompoundTag root){
        var data=new DungeonStateStore();
        var saved=root.getCompound("Rooms");
        for(String key:saved.getAllKeys()){
            var room=new DungeonRoomController();room.load(saved.getCompound(key));data.rooms.put(key,room);
        }
        var encounters=root.getCompound("Encounters");
        for(String key:encounters.getAllKeys())data.encounters.put(key,DungeonEncounterState.load(encounters.getCompound(key)));
        var rewards=root.getCompound("Rewards");
        for(String key:rewards.getAllKeys())data.rewards.put(key,DungeonRewardReceipt.load(rewards.getCompound(key)));
        return data;
    }
    @Override public CompoundTag save(CompoundTag root){
        root.putInt("Version",2);var tag=new CompoundTag();rooms.forEach((key,value)->tag.put(key,value.save()));root.put("Rooms",tag);
        var encountersTag=new CompoundTag();encounters.forEach((key,value)->encountersTag.put(key,value.save()));root.put("Encounters",encountersTag);
        var rewardsTag=new CompoundTag();rewards.forEach((key,value)->rewardsTag.put(key,value.save()));root.put("Rewards",rewardsTag);return root;
    }
}

package com.dynasty.dungeon;

import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.world.item.ItemStack;
import net.minecraft.server.level.ServerPlayer;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

/** Persistent reward escrow: full inventories leave stacks here, never on the floor. */
public final class DungeonRewardReceipt {
    private final UUID owner;
    private final List<ItemStack> pending;
    DungeonRewardReceipt(UUID owner,List<ItemStack> items){
        this.owner=owner;pending=new ArrayList<>(items.stream().filter(s->!s.isEmpty()).map(ItemStack::copy).toList());
    }
    public UUID owner(){return owner;}
    public boolean empty(){return pending.isEmpty();}
    public boolean deliver(ServerPlayer player){
        if(!player.getUUID().equals(owner))return false;
        boolean changed=false;
        for(var stack:pending){int before=stack.getCount();player.getInventory().add(stack);changed|=stack.getCount()!=before;}
        pending.removeIf(ItemStack::isEmpty);
        if(changed)player.containerMenu.broadcastChanges();
        return changed;
    }
    public CompoundTag save(){
        var tag=new CompoundTag();if(owner!=null)tag.putUUID("Owner",owner);
        var stacks=new ListTag();pending.forEach(s->stacks.add(s.save(new CompoundTag())));tag.put("Pending",stacks);return tag;
    }
    public static DungeonRewardReceipt load(CompoundTag tag){
        var items=new ArrayList<ItemStack>();
        for(var item:tag.getList("Pending",10))if(items.size()<128)items.add(ItemStack.of((CompoundTag)item));
        // A malformed receipt retains its key with no claimant; it cannot reroll loot.
        return new DungeonRewardReceipt(tag.hasUUID("Owner")?tag.getUUID("Owner"):null,items);
    }
}

static String worldKey(ResourceLocation dungeon){return dungeon+"/first_kill/world";}
static String playerKey(ResourceLocation dungeon,UUID player){return dungeon+"/first_kill/player/"+player;}
public static Result claimChensha(ServerLevel level,UUID instance,BlockPos origin,ServerPlayer player){
    if(!level.dimension().location().equals(DungeonDefinition.CHENSHA.dimension()))return Result.INELIGIBLE;
    if(!entrant(player,origin))return Result.INELIGIBLE;
    var store=DungeonStateStore.get(level);var state=store.encounter(instance,DungeonDefinition.CHENSHA.id().toString(),false);
    return claim(level,store,state,DungeonDefinition.CHENSHA.id(),player,BINDINGS.get(CHENSHA_BOSS));
}
static Result claim(ServerLevel level,DungeonStateStore store,DungeonEncounterState state,ResourceLocation dungeon,ServerPlayer player,Binding binding){
    if(state==null||state.phase()!=DungeonEncounterState.Phase.DEFEATED)return Result.SEALED;
    if(!state.participant(player.getUUID()))return Result.INELIGIBLE;
    if(!ready(level,binding)||!state.bossType().equals(binding.bossType()))return Result.MISSING_DEPENDENCY;
    var worldKey=worldKey(dungeon);var playerKey=playerKey(dungeon,player.getUUID());
    var world=store.reward(worldKey);var personal=store.reward(playerKey);
    // Generate both bundles before reserving either one: missing/empty tables cannot consume a first kill.
    var worldItems=world==null?loot(level,binding.worldLoot(),player):List.<ItemStack>of();
    var playerItems=binding.playerLoot()!=null&&personal==null?loot(level,binding.playerLoot(),player):List.<ItemStack>of();
    if(world==null&&(worldItems.isEmpty()||worldItems.size()>128)
        ||binding.playerLoot()!=null&&personal==null&&(playerItems.isEmpty()||playerItems.size()>128))return Result.MISSING_DEPENDENCY;
    if(world==null)world=store.reserveReward(worldKey,player.getUUID(),worldItems);
    if(binding.playerLoot()!=null&&personal==null)personal=store.reserveReward(playerKey,player.getUUID(),playerItems);
    boolean changed=world.deliver(player);if(personal!=null)changed|=personal.deliver(player);
    if(changed)store.setDirty();
    boolean pending=player.getUUID().equals(world.owner())&&!world.empty()||personal!=null&&!personal.empty();
    return pending?Result.INVENTORY_FULL:changed?Result.CLAIMED:Result.ALREADY_CLAIMED;
}
private static List<ItemStack> loot(ServerLevel level,ResourceLocation table,ServerPlayer player){
    var params=new LootParams.Builder(level).withParameter(LootContextParams.ORIGIN,player.position())
        .withOptionalParameter(LootContextParams.THIS_ENTITY,player).withLuck(player.getLuck()).create(LootContextParamSets.CHEST);
    return level.getServer().getLootData().getLootTable(table).getRandomItems(params);
}
